/bin/bash -lc "python3 - <<'PY'
import ast,hashlib,json
from pathlib import Path
r=json.load(open('runtime_resolved.json')); p=json.load(open('proposal.json'))
def validate(value,schema,path='"'$'"'):
 typ=schema.get('type')
 matches={'object':lambda v:isinstance(v,dict),'array':lambda v:isinstance(v,list),'string':lambda v:isinstance(v,str),'boolean':lambda v:isinstance(v,bool),'integer':lambda v:isinstance(v,int) and not isinstance(v,bool),'number':lambda v:isinstance(v,(int,float)) and not isinstance(v,bool),'null':lambda v:v is None}
 if typ: assert matches[typ](value),(path,typ)
 if 'const' in schema: assert value==schema['const'],path
 if 'enum' in schema: assert value in schema['enum'],path
 if isinstance(value,dict):
  assert set(schema.get('required',[]))<=set(value),(path,'required')
  props=schema.get('properties',{})
  if schema.get('additionalProperties') is False: assert set(value)<=set(props),(path,'additional')
  for k,v in value.items():
   if k in props: validate(v,props[k],path+'.'+k)
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),path
  for i,v in enumerate(value): validate(v,schema.get('items',{}),path+'['+str(i)+']')
 if isinstance(value,str): assert len(value)>=schema.get('minLength',0),path
validate(p['study'],r['study_schema'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert all(v['role'] in ('candidate','control') and v['file'].endswith('.py') for v in p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
for v in p['variants']:
 source=Path(v['file']).read_text(); ast.parse(source)
 digest=hashlib.sha256(source.encode()).hexdigest(); assert digest in v['note']
assert len(p['knowledge_assessments'])==len({a['knowledge_id'] for a in p['knowledge_assessments']})
print('PASS: complete prospective study schema, protocol/evidence references, four standalone source/config/hash bindings and knowledge assessments.')
print('DELIVERABLES: proposal.json, candidate.py, aligned_centroid.py, rotated_event.py, rotated_centroid.py')
for f in ['runtime_resolved.json','build_variants.py','write_proposal.py']: Path(f).unlink()
PY"

